["from typing import List

def remove_empty_and_sort(strings: List[str]) -> List[str]:
    filtered = [s for s in strings if s]
    return sorted(filtered, key=len, reverse=True)

example = ["banana", "", "apple", "", "fig", "cherry"]
print(remove_empty_and_sort(example))"]
